package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.config.*;
import com.lianxibu.site.domain.sources.SourceDayRunRegistration;
import java.time.*;
import java.util.*;
import javax.sql.DataSource;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.runner.ApplicationContextRunner;
import org.springframework.transaction.PlatformTransactionManager;

class CatalogDayReportProofConfigurationTest {
    static final List<String> FLAGS=List.of("site.browser.enabled","site.content.enabled","site.articles.enabled","site.sources.enabled","site.execution.enabled","site.collector.enabled","site.sources.day-roster.enabled","site.execution.report-preparation.enabled");
    CatalogDayAnalysisProofConfiguration.Graphs graphs(DataSource source,PlatformTransactionManager tx,Clock clock){var cohorts=mock(SourceDayCohortSealService.class);var runs=mock(SourceDayRunRegistration.Api.class);var map=new LinkedHashMap<String,CatalogDayAnalysisProofGraph>();for(String category:CatalogSourceProofConfiguration.CATEGORIES){var sourceGraph=new CatalogSourceProofGraph(source,tx,clock,()->{throw new AssertionError("cold settings");},()->{throw new AssertionError("cold gate");},category);map.put(category,new CatalogDayAnalysisProofGraph(source,tx,clock,cohorts,runs,sourceGraph,()->{throw new AssertionError("cold settings");},()->{throw new AssertionError("cold gate");},category));}return new CatalogDayAnalysisProofConfiguration.Graphs(map);}
    @Test void DefaultsAndEachMissingFlagKeepComponentsAndExecutorsAbsent(){var runner=new ApplicationContextRunner().withUserConfiguration(CatalogDayReportProofConfiguration.class);runner.run(c->{assertNull(c.getStartupFailure());assertFalse(c.containsBean("catalogDayReportComponents"));assertFalse(c.containsBean("catalogDayReportAggregate"));});for(String missing:FLAGS)runner.withPropertyValues(FLAGS.stream().filter(f->!f.equals(missing)).map(f->f+"=true").toArray(String[]::new)).run(c->{assertNull(c.getStartupFailure());assertFalse(c.containsBean("catalogDayReportComponents"));assertFalse(c.containsBean("catalogDayReportAggregate"));assertTrue(c.getBeansOfType(java.util.concurrent.ScheduledExecutorService.class).isEmpty());});}
    @Test void ColdFormalBeanUsesFourActualGraphsAndImmutableMandatoryRoutingWithoutIo(){var source=mock(DataSource.class);var tx=mock(PlatformTransactionManager.class);var clock=mock(Clock.class);var graphs=graphs(source,tx,clock);new ApplicationContextRunner().withUserConfiguration(CatalogDayReportProofConfiguration.class).withPropertyValues(FLAGS.stream().map(f->f+"=true").toArray(String[]::new)).withBean(DataSource.class,()->source).withBean(PlatformTransactionManager.class,()->tx).withBean(CatalogDayAnalysisProofConfiguration.Graphs.class,()->graphs).run(c->{assertNull(c.getStartupFailure());var components=c.getBean(CatalogDayReportProofConfiguration.Components.class);assertEquals(1,c.getBeansOfType(CatalogDayReportAggregateService.class).size());assertSame(c.getBean("catalogDayReportAggregate"),c.getBean(CatalogDayReportAggregateService.class));assertEquals(Set.copyOf(CatalogSourceProofConfiguration.CATEGORIES),components.byCategory().keySet());assertEquals(4,components.byCategory().values().stream().distinct().count());assertThrows(UnsupportedOperationException.class,()->components.byCategory().clear());assertThrows(RuntimeException.class,()->components.component("news_tech"));assertTrue(c.getBeansOfType(java.util.concurrent.ScheduledExecutorService.class).isEmpty());assertFalse(components.toString().contains("fictional"));});verifyNoInteractions(source,tx,clock);}
    @Test void AggregateBeanCannotStartWithoutMandatoryOriginalComponents(){new ApplicationContextRunner().withBean(PlatformTransactionManager.class,()->mock(PlatformTransactionManager.class)).withBean(CatalogDayReportAggregateService.class,()->new CatalogDayReportProofConfiguration().catalogDayReportAggregate(null,mock(PlatformTransactionManager.class))).run(c->assertNotNull(c.getStartupFailure()));}
    @Test void EnabledButMissingOriginalNativeGraphsFailsStartupWithoutFallback(){new ApplicationContextRunner().withUserConfiguration(CatalogDayReportProofConfiguration.class).withPropertyValues(FLAGS.stream().map(f->f+"=true").toArray(String[]::new)).withBean(DataSource.class,()->mock(DataSource.class)).withBean(PlatformTransactionManager.class,()->mock(PlatformTransactionManager.class)).run(c->assertNotNull(c.getStartupFailure()));}
}
